<style>
.rk-commerce{--c-paper:#fffdf9;--c-cream:#f8f3ea;--c-ink:#35251f;--c-muted:#82746b;--c-line:#e9ded2;--c-terra:#c96d4c;--c-terra-dark:#a85135;color:var(--c-ink)}
.rk-commerce *{box-sizing:border-box}.rk-commerce a{color:inherit}.rk-commerce-head{display:flex;align-items:flex-end;justify-content:space-between;gap:18px;margin-bottom:24px}.rk-commerce-head h1{font-size:clamp(1.65rem,2.7vw,2.35rem);margin:4px 0 8px;letter-spacing:-.035em}.rk-commerce-head p{margin:0;color:var(--c-muted);max-width:720px}.rk-commerce-eyebrow{font-size:.72rem;letter-spacing:.14em;text-transform:uppercase;font-weight:800;color:var(--c-terra)}
.rk-commerce-btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;background:var(--c-terra);color:#fff!important;border:1px solid var(--c-terra);border-radius:12px;padding:11px 15px;font-weight:750;text-decoration:none;cursor:pointer;min-height:42px}.rk-commerce-btn:hover{background:var(--c-terra-dark)}.rk-commerce-btn.ghost{background:var(--c-paper);color:var(--c-ink)!important;border-color:var(--c-line)}.rk-commerce-btn.danger{background:#fff4f1;border-color:#f2c7ba;color:#a23c26!important}.rk-commerce-btn.small{padding:8px 11px;font-size:.86rem;min-height:36px}
.rk-commerce-panel{background:var(--c-paper);border:1px solid var(--c-line);border-radius:18px;padding:22px;margin-bottom:20px;box-shadow:0 8px 28px rgba(55,37,26,.04)}.rk-commerce-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.rk-commerce-grid.two{grid-template-columns:minmax(0,1.3fr) minmax(300px,.7fr)}.rk-commerce-card{background:var(--c-paper);border:1px solid var(--c-line);border-radius:16px;overflow:hidden;display:flex;flex-direction:column;min-width:0}.rk-commerce-card-image{height:190px;background:var(--c-cream);display:flex;align-items:center;justify-content:center;overflow:hidden}.rk-commerce-card-image img{width:100%;height:100%;object-fit:cover}.rk-commerce-no-image{color:var(--c-muted);font-size:.85rem;text-align:center;padding:20px}.rk-commerce-card-body{padding:16px;display:flex;flex-direction:column;gap:10px;flex:1}.rk-commerce-card-body h3{margin:0;font-size:1.1rem}.rk-commerce-card-body p{margin:0;color:var(--c-muted);font-size:.9rem;line-height:1.55}.rk-commerce-meta{font-size:.76rem;color:var(--c-muted);text-transform:uppercase;letter-spacing:.08em}.rk-commerce-price{font-size:1.12rem;font-weight:850}.rk-commerce-inline{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.rk-commerce-inline input[type=number]{width:78px}.rk-commerce-input,.rk-commerce-select,.rk-commerce-textarea{width:100%;border:1px solid #ded0c3;border-radius:10px;background:#fff;padding:11px 12px;color:var(--c-ink);font:inherit;min-height:42px}.rk-commerce-textarea{min-height:100px;resize:vertical}.rk-commerce-field{display:grid;gap:7px;font-size:.9rem;font-weight:700}.rk-commerce-field small{font-weight:400;color:var(--c-muted)}.rk-commerce-form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.rk-commerce-field.full{grid-column:1/-1}.rk-commerce-errors{border:1px solid #f0b9aa;background:#fff4f1;color:#8e2e1c;border-radius:12px;padding:14px 18px;margin-bottom:18px}.rk-commerce-errors ul{margin:7px 0 0;padding-left:20px}.rk-commerce-alert{padding:12px 15px;border-radius:12px;background:#edf7f0;border:1px solid #c6e5d0;color:#23613a;margin-bottom:18px}.rk-commerce-note{padding:13px 15px;border-radius:12px;background:var(--c-cream);color:var(--c-muted);font-size:.9rem}.rk-commerce-table-wrap{overflow-x:auto}.rk-commerce-table{border-collapse:collapse;width:100%;min-width:690px}.rk-commerce-table th,.rk-commerce-table td{text-align:left;padding:13px 12px;border-bottom:1px solid var(--c-line);vertical-align:middle}.rk-commerce-table th{color:var(--c-muted);font-size:.74rem;text-transform:uppercase;letter-spacing:.08em;background:#fbf7f1}.rk-commerce-table td small{display:block;color:var(--c-muted);margin-top:4px}.rk-commerce-product{display:flex;gap:12px;align-items:center;min-width:190px}.rk-commerce-thumb{width:58px;height:58px;flex:0 0 auto;border-radius:10px;overflow:hidden;object-fit:cover;background:var(--c-cream);display:grid;place-items:center;color:var(--c-muted);font-size:.72rem}.rk-commerce-total{display:flex;justify-content:space-between;gap:16px;padding:10px 0;border-bottom:1px solid var(--c-line)}.rk-commerce-total.final{border:0;padding-top:16px;font-weight:850;font-size:1.15rem}.rk-commerce-summary{position:sticky;top:18px;align-self:start}.rk-commerce-pill{display:inline-flex;align-items:center;border-radius:999px;padding:5px 9px;font-size:.76rem;font-weight:750;background:#f1e8df;color:#5a463a}.rk-commerce-pill.green{background:#e6f5eb;color:#246440}.rk-commerce-pill.orange{background:#fff1dc;color:#8d5a08}.rk-commerce-pill.red{background:#ffebe7;color:#9b3324}.rk-commerce-section-title{margin:28px 0 14px;display:flex;justify-content:space-between;align-items:flex-end;gap:12px}.rk-commerce-section-title h2{margin:0;font-size:1.35rem}.rk-commerce-section-title p{margin:5px 0 0;color:var(--c-muted)}.rk-commerce-empty{text-align:center;padding:34px 16px;color:var(--c-muted)}.rk-commerce-empty h3{color:var(--c-ink);margin:8px 0}.rk-commerce-status-form{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.rk-commerce-status-form select{min-width:160px}.rk-commerce-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:20px}.rk-commerce-kpi{border:1px solid var(--c-line);background:var(--c-paper);border-radius:14px;padding:16px}.rk-commerce-kpi span{font-size:.83rem;color:var(--c-muted)}.rk-commerce-kpi strong{display:block;font-size:1.5rem;margin:7px 0 4px}.rk-commerce-actions{display:flex;gap:8px;flex-wrap:wrap}.rk-commerce-receipt{max-width:760px;margin:auto;background:#fff;border:1px solid var(--c-line);border-radius:16px;padding:28px}.rk-commerce-receipt-head{text-align:center;padding-bottom:18px;border-bottom:1px dashed #cdbdae}.rk-commerce-receipt-head h1{margin:4px 0}.rk-commerce-receipt-lines{width:100%;border-collapse:collapse;margin:18px 0}.rk-commerce-receipt-lines td{padding:8px 0;border-bottom:1px dashed #eadfd4}.rk-commerce-print-only{display:none}.rk-commerce-section-divider{border:0;border-top:1px solid var(--c-line);margin:18px 0}
@media(max-width:1050px){.rk-commerce-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.rk-commerce-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}.rk-commerce-grid.two{grid-template-columns:1fr}.rk-commerce-summary{position:static}}
@media(max-width:650px){.rk-commerce-head{align-items:flex-start;flex-direction:column}.rk-commerce-grid,.rk-commerce-form-grid{grid-template-columns:1fr}.rk-commerce-panel{padding:15px}.rk-commerce-card-image{height:210px}.rk-commerce-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}.rk-commerce-receipt{padding:18px}}
@media print{body{background:#fff!important}.rk-sidebar,.rk-topbar,.rk-footer,.rk-no-print,.rk-commerce-head .rk-commerce-btn{display:none!important}.rk-main,.rk-content{margin:0!important;padding:0!important;width:100%!important}.rk-commerce-receipt{border:0;border-radius:0;box-shadow:none;max-width:none;padding:0}.rk-commerce-print-only{display:block}.rk-app{display:block!important}}

/* Checkout UI alignment: normalize one-line controls across the commerce module. */
.rk-commerce .rk-commerce-form-grid{align-items:start;grid-auto-rows:min-content}
.rk-commerce .rk-commerce-field{align-content:start;gap:8px;min-width:0;line-height:1.4}
.rk-commerce .rk-commerce-field>span{display:block;line-height:1.35}
.rk-commerce .rk-commerce-input:not([type="file"]),
.rk-commerce .rk-commerce-select{display:block;width:100%;height:48px;min-height:48px;box-sizing:border-box;padding:0 12px;border-radius:10px;font:inherit;font-size:.94rem;line-height:1.2}
.rk-commerce .rk-commerce-select{padding-right:36px}
.rk-commerce .rk-commerce-input[type="file"]{display:block;width:100%;height:48px;min-height:48px;box-sizing:border-box;padding:5px 8px;font:inherit;font-size:.88rem;line-height:1.2}
.rk-commerce .rk-commerce-input[type="file"]::file-selector-button{margin:0 10px 0 0;padding:7px 10px;border:1px solid var(--c-line);border-radius:7px;background:var(--c-cream);color:var(--c-ink);font:inherit;cursor:pointer}
.rk-commerce .rk-commerce-textarea{display:block;width:100%;min-height:108px;box-sizing:border-box;padding:12px;font:inherit;font-size:.94rem;line-height:1.5}
.rk-commerce .rk-commerce-field small{display:block;line-height:1.45}
.rk-commerce .rk-commerce-field[hidden]{display:none!important}
.rk-commerce .rk-checkout-section-heading{margin:0 0 20px;font-size:1.2rem;line-height:1.35;letter-spacing:-.015em}
.rk-commerce .rk-checkout-optional{font-weight:400;color:var(--c-muted);font-size:.86em}
.rk-commerce .rk-checkout-layout{align-items:start;gap:20px}
.rk-commerce .rk-checkout-summary{padding:22px}
.rk-commerce .rk-checkout-line-item{align-items:flex-start;line-height:1.45}
.rk-commerce .rk-checkout-line-item>span{min-width:0;overflow-wrap:anywhere}
.rk-commerce .rk-checkout-line-item strong{white-space:nowrap;font-variant-numeric:tabular-nums}
.rk-commerce .rk-checkout-quantity{color:var(--c-muted);white-space:nowrap}
.rk-commerce .rk-checkout-subtotal{margin-top:4px;padding:16px 0;font-size:1.02rem;font-weight:800}
.rk-commerce .rk-checkout-subtotal strong{font-variant-numeric:tabular-nums;white-space:nowrap}
.rk-commerce .rk-checkout-summary-note{margin-top:8px;line-height:1.55}
.rk-commerce .rk-checkout-submit{width:100%;min-height:48px;margin-top:18px}
.rk-commerce .rk-checkout-secure-note{margin:11px 0 0;color:var(--c-muted);font-size:.8rem;line-height:1.5;text-align:center}
@media(max-width:650px){
  .rk-commerce .rk-checkout-layout{gap:4px}
  .rk-commerce .rk-checkout-summary{padding:18px}
  .rk-commerce .rk-commerce-form-grid{gap:18px}
}
</style>
